 $('#dre-prev').onclick=()=>{page--;load()};$('#dre-next').onclick=()=>{page++;load()};host.querySelectorAll('[data-edit-expense]').forEach(b=>b.onclick=()=>expenseForm(b.dataset.editExpense));
