 const f=$('form',slot);f.onsubmit=async e=>{e.preventDefault();const b=$('[type=submit]',f);b.disabled=true;try{await api('/settings',{taxRateBps:parse(f.elements.taxRate.value),vehicleComponents:[...f.querySelectorAll('[name=components]:checked')].map(x=>x.value),vehicleNotes:f.elements.vehicleNotes.value},'PUT');$('.dre-error',f).textContent='';notice('Premissas salvas. Meses já abertos preservados.');}catch(e){$('.dre-error',f).textContent=e.message}finally{b.disabled=false}};
